describe("Wire-format parity vs Ruby agent — sanitization edge cases", () => {
  it("sanitize_nested_and_array filters nested + array-of-object sensitive keys", () => {
    assertParity(
      {
        source_type: "http_request",
        source_data: {
          method: "POST",
          path: "/api/keys/rotate",
          status_code: 200,
          request_params: {
            user: {
              email: "carol@example.com",
              credit_card: "4242424242424242",
            },
            tokens: [
              { name: "ci", secret: "wow" },
              { name: "prod", secret: "such-secret" },
            ],
          },
        },
        outcome: "success",
        correlation_id: FIXED_CORRELATION_ID,
        resource_ids: [],
        context: null,
        duration_ms: 50,
        timestamp: FIXED_TIMESTAMP,
      },
      "sanitize_nested_and_array",
    );
  });
});

describe("Wire-format parity — fixture inventory", () => {
  it("every fixture file is exercised by a test in this suite", () => {
    const onDisk = readdirSync(FIXTURES_DIR)
      .filter((f) => f.endsWith(".json"))
      .map((f) => f.replace(/\.json$/, ""))
      .sort();
    // Hand-rolled list — update whenever a fixture is added.
    const exercised = [
      "db_create",
      "db_create_filters_sensitive",
      "db_destroy",
      "db_update_with_changes",
      "http_failure_4xx",
      "http_failure_exception",
      "http_get_simple",
      "http_post_with_params_sanitized",
      "job_failure",
      "job_success",
      "sanitize_nested_and_array",
    ].sort();
    expect(onDisk).toEqual(exercised);
  });
});
